#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/*
 * Merge Sort - A recursive implementation of the Merge Sort algorithm.
 * 
 * This implementation uses the "divide and conquer" strategy:
 * 1. Divide the array into two halves.
 * 2. Recursively sort each half.
 * 3. Merge the two sorted halves back together.
 * 
 * Time Complexity: O(n log n) on average
 * Space Complexity: O(n) for the auxiliary array used during merging
 * 
 * Note: This implementation uses a fixed-size array for the merge step.
 */

void merge(int arr[], int left, int mid, int right) {
    /* Base case: if the subarrays have only one element, they are sorted */
    if (left == right) {
        return;
    }

    /* Choose a pivot element */
    int pivot = arr[mid];

    /* Partition the array around the pivot */
    int i = left;
    int j = mid + 1;

    /* Move elements smaller than pivot to smaller indices */
    while (i <= mid && j <= right) {
        if (arr[i] < pivot) {
            i++;
        } else if (arr[j] < pivot) {
            j++;
        }
    }

    /* Swap pivot with the element at the partition point */
    int temp = arr[mid];
    arr[mid] = arr[i];
    arr[i] = temp;

    /* Recursively sort the left and right subarrays */
    merge(arr, left, mid, j - 1);
    merge(arr, mid + 1, right, i);
}

/*
 * Example usage:
 * 
 * int main() {
 *     int arr[] = {3, 2, 1, 4, 5, 6};
 *     merge(arr, 0, 5, 5);
 *     printf("Sorted array: ");
 *     for (int i = 0; i < 6; i++) {
 *         printf("%d ", arr[i]);
 *     }
 *     printf("\n");
 *     return 0;
 * }
 */

int main() {
    int arr[] = {3, 2, 1, 4, 5, 6};
    merge(arr, 0, 5, 5);

    printf("Sorted array: ");
    for (int i = 0; i < 6; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

### Key Features of This Implementation:

1. **Recursive Structure**: The `merge` function is recursive, dividing the array into smaller subarrays until they are sorted.
2. **Partitioning**: The `partition` function uses two pointers (`i` and `j`) to find the correct pivot position.
3. **Swapping**: The pivot is swapped with the element at the partition point to ensure the pivot is in its correct sorted position.
4. **Base Case**: The base case handles the case where the subarrays have only one element, preventing infinite recursion.
5. **In-Place Partitioning**: The implementation uses a fixed-size array for the partitioning, which is efficient for small arrays.

### Usage Example:
```c
