    int arr[] = {3, 2, 1, 4, 5, 6};
    merge(arr, 0, 5, 5);
    printf("Sorted array: ");
    for (int i = 0; i < 6; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

This implementation is efficient and easy to understand, making it a good starting point for learning the Merge Sort algorithm.
